commands.command:
mysql -uroot <<SQL
SET PASSWORD FOR 'root'@'localhost' = PASSWORD('${ROOT_PASS}');
CREATE USER 'sstuser'@'localhost' IDENTIFIED BY [REDACTED]
GRANT RELOAD, LOCK TABLES, PROCESS, REPLICATION CLIENT ON *.* TO 'sstuser'@'localhost';
FLUSH PRIVILEGES;
SQL
echo EXIT:$?

mysql -uroot -p"${ROOT_PASS}" <<SQL
CREATE DATABASE appdb;
CREATE TABLE appdb.orders (id INT PRIMARY KEY AUTO_INCREMENT, note VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO appdb.orders (note) VALUES ('order-1'), ('order-2'), ('order-3');
CREATE USER 'appuser'@'%' IDENTIFIED BY [REDACTED]
GRANT ALL PRIVILEGES ON appdb.* TO 'appuser'@'%';
FLUSH PRIVILEGES;
SELECT * FROM appdb.orders;
SQL
echo EXIT:$?

